def insertion_sort_rec(a: list[int], n: int | None = None) -> None:
    if n is None:
        n = len(a)
    if n <= 1:
        return
    insertion_sort_rec(a, n - 1)
    key = a[n - 1]
    j = n - 2
    while j >= 0 and a[j] > key:
        a[j + 1] = a[j]
        j -= 1
    a[j + 1] = key
